'use client';

import React, { useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { 
  BookOpen, ArrowLeft, MessageSquare, Sparkles
} from 'lucide-react';
import AITeacherDrawer from '@/components/AITeacherDrawer';

export default function StudentDashboard() {
  const params = useParams();
  const router = useRouter();
  const rawStudent = (params.student as string)?.toLowerCase();
  const isAvril = rawStudent === 'avril';
  const studentName = isAvril ? 'Avril' : 'Gael';

  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [selectedSubject, setSelectedSubject] = useState(isAvril ? 'Ciencias' : 'Exploración');

  const studentConfig = isAvril ? {
    name: 'Avril',
    grade: '8vo de Básica',
    badge: '🐶 Mundo Snoopy',
    methodology: 'Montessori / Charlotte Mason',
    colorAccent: 'border-indigo-500 bg-indigo-500/10 text-indigo-400',
    btnBg: 'bg-indigo-600 hover:bg-indigo-500',
    teacher: { name: 'Dra. Elena (IA Ciencias)', avatar: '' },
    subjects: ['Ciencias', 'Investigación', 'Matemáticas', 'Literatura']
  } : {
    name: 'Gael',
    grade: '4to de Básica',
    badge: '🍄 Mundo Mario Bros',
    methodology: 'Misiones & Gamificación',
    colorAccent: 'border-amber-500 bg-amber-500/10 text-amber-400',
    btnBg: 'bg-amber-600 hover:bg-amber-500',
    teacher: { name: 'Prof. Mario (IA Exploración)', avatar: '' },
    subjects: ['Exploración', 'Lectoescritura', 'Matemáticas', 'Retos']
  };

  const dailyClass = {
    theme: isAvril ? 'El método científico' : 'La aventura de las fracciones',
    description: isAvril 
      ? 'Aprenderemos a formular hipótesis haciendo experimentos sencillos.' 
      : 'Usa tus piezas para dividir un grupo en partes iguales.'
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col md:flex-row">
      <aside className="w-full md:w-64 bg-slate-900 border-r border-slate-800 p-5 flex flex-col justify-between shrink-0">
        <div className="space-y-6">
          <button onClick={() => router.push('/')} className="flex items-center gap-2 text-xs font-bold text-slate-400 hover:text-white">
            <ArrowLeft className="w-4 h-4" /> Volver
          </button>
          <div className="p-4 rounded-2xl bg-slate-800/80 border border-slate-700/60 flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-slate-700 flex items-center justify-center font-bold text-white">
              {studentName.charAt(0)}
            </div>
            <div>
              <h2 className="font-bold text-sm text-white">{studentName}</h2>
              <p className="text-[11px] text-slate-400">{studentConfig.grade}</p>
              <span className={`inline-block text-[9px] px-2 py-0.5 rounded font-semibold ${studentConfig.colorAccent}`}>
                {studentConfig.badge}
              </span>
            </div>
          </div>
          <nav className="space-y-1">
            <div className="px-3 py-2 text-[10px] font-bold text-slate-500 uppercase">Materias</div>
            {studentConfig.subjects.map((sub) => (
              <button
                key={sub}
                onClick={() => setSelectedSubject(sub)}
                className={`w-full text-left px-3 py-2 rounded-xl text-xs font-medium flex items-center justify-between ${selectedSubject === sub ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' : 'text-slate-400 hover:bg-slate-800'}`}
              >
                <span>{sub}</span>
                {selectedSubject === sub && <Sparkles className="w-3.5 h-3.5 text-indigo-400" />}
              </button>
            ))}
          </nav>
        </div>
        <div className="mt-6 p-3 rounded-xl bg-slate-800/40 border border-slate-800 text-[11px] text-slate-400">
          <span className="font-bold text-slate-300 block">Método</span>
          <p>{studentConfig.methodology}</p>
        </div>
      </aside>

      <main className="flex-1 p-6 md:p-8 space-y-6 overflow-y-auto">
        <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-800 pb-6">
          <div>
            <h1 className="text-2xl font-black text-white">Espacio de Aprendizaje - {selectedSubject}</h1>
            <p className="text-xs text-slate-400 mt-1">Wisdom School • Curriculum Internacional</p>
          </div>
          <button onClick={() => setIsDrawerOpen(true)} className={`px-5 py-2.5 rounded-xl font-bold text-xs text-white shadow-lg flex items-center gap-2 ${studentConfig.btnBg}`}>
            <MessageSquare className="w-4 h-4" />
            <span>Consultar al Tutor IA ({studentConfig.teacher.name})</span>
          </button>
        </header>

        <div className="p-6 rounded-2xl bg-slate-900 border border-slate-800 space-y-4">
          <div className="flex items-center gap-2 text-xs text-amber-400 font-bold uppercase">
            <BookOpen className="w-4 h-4" /> Lección del Día
          </div>
          <h3 className="text-lg font-bold text-white">{dailyClass.theme}</h3>
          <p className="text-xs sm:text-sm text-slate-300 leading-relaxed">{dailyClass.description}</p>
          <div className="pt-4 border-t border-slate-800">
            <button onClick={() => setIsDrawerOpen(true)} className="px-4 py-2 rounded-lg bg-indigo-600/20 hover:bg-indigo-600/30 text-indigo-300 border border-indigo-500/30 text-xs font-semibold flex items-center gap-2">
              <Sparkles className="w-3.5 h-3.5" />
              <span>Pedir Pista Socrática al Profesor</span>
            </button>
          </div>
        </div>
      </main>

      <AITeacherDrawer
        isOpen={isDrawerOpen}
        onClose={() => setIsDrawerOpen(false)}
        student={isAvril ? 'Avril' : 'Gael'}
        asignatura={selectedSubject}
        teacher={studentConfig.teacher}
        dailyClass={{ theme: dailyClass.theme }}
      />
    </div>
  );
}

