'use client';

import React, { useState, useRef, useEffect } from 'react';
import { X, Loader2, Send } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

interface Mensaje {
  id?: string;
  role: 'estudiante' | 'profesor';
  texto: string;
  timestamp?: string;
}

interface TeacherInfo {
  name: string;
  avatar: string;
}

interface AITeacherDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  student: 'Avril' | 'Gael';
  asignatura: string;
  teacher: TeacherInfo;
  dailyClass?: { theme: string };
}

export default function AITeacherDrawer({
  isOpen,
  onClose,
  student,
  asignatura,
  teacher,
  dailyClass = { theme: 'Exploración e Investigación' }
}: AITeacherDrawerProps) {
  const [messages, setMessages] = useState<Mensaje[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
    const saved = localStorage.getItem(`chatHistory_${student}_${asignatura}`);
    if (saved) {
      try { setMessages(JSON.parse(saved)); } catch (e) {}
    }
  }, [student, asignatura]);

  useEffect(() => {
    if (isMounted) {
      localStorage.setItem(`chatHistory_${student}_${asignatura}`, JSON.stringify(messages));
    }
  }, [messages, isMounted, student, asignatura]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isLoading]);

  if (!isOpen || !isMounted) return null;

  const handleSendMessage = async (textToSend?: string) => {
    const text = textToSend || input;
    if (!text.trim() || isLoading) return;

    const timeString = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const userMsg: Mensaje = { id: Date.now().toString(), role: 'estudiante', texto: text, timestamp: timeString };

    const updated = [...messages, userMsg];
    setMessages(updated);
    if (!textToSend) setInput('');
    setIsLoading(true);

    try {
      const res = await fetch('/api/profesor', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          preguntaEstudiante: text,
          asignatura,
          estudiante: student,
          temaDia: dailyClass.theme,
          historialConversacion: messages.map(m => ({ role: m.role, texto: m.texto })),
        }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Error en la respuesta.');

      setMessages([...updated, {
        id: Date.now().toString(),
        role: 'profesor',
        texto: data.respuesta,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }]);
    } catch (error: any) {
      setMessages([...updated, {
        id: Date.now().toString(),
        role: 'profesor',
        texto: error.message || "Disculpa, estoy organizando mis apuntes.",
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const quickPrompts = ['¿Me das una pista?', '¿Qué debo razonar primero?', '¿Un ejemplo cotidiano?'];

  return (
    <div className="fixed inset-0 z-50 overflow-hidden flex justify-end bg-black/60 backdrop-blur-sm">
      <div className="w-full max-w-lg bg-slate-900 border-l border-slate-700 shadow-2xl flex flex-col h-full">
        {/* Cabecera */}
        <div className="p-4 border-b border-slate-800 bg-slate-900 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-indigo-600 text-white flex items-center justify-center font-bold text-sm">
              {teacher.avatar ? <img src={teacher.avatar} alt={teacher.name} className="w-full h-full object-cover rounded-2xl" /> : teacher.name.charAt(0)}
            </div>
            <div>
              <h3 className="text-sm font-bold text-white">{teacher.name}</h3>
              <span className="text-[10px] bg-indigo-500/20 text-indigo-300 px-2 py-0.5 rounded-full">Tutor IA Wisdom</span>
            </div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white"><X className="w-5 h-5" /></button>
        </div>
        
        {/* Banner Contexto */}
        <div className="px-4 py-2 bg-indigo-950/40 border-b border-slate-800 flex items-center justify-between text-xs text-indigo-300">
          <span className="truncate pr-2">Contexto: {dailyClass.theme}</span>
          <span className="text-[10px] uppercase font-bold text-amber-400 bg-amber-400/10 px-2 py-0.5 rounded border border-amber-400/20">Método Socrático</span>
        </div>

        {/* Mensajes */}
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
          {messages.map((msg, i) => {
            const isUser = msg.role === 'estudiante';
            return (
              <div key={msg.id || i} className={`flex gap-3 ${isUser ? 'justify-end' : 'justify-start'}`}>
                {!isUser && (
                  <div className="w-7 h-7 rounded-lg bg-indigo-600 text-white flex items-center justify-center text-xs font-bold shrink-0 mt-1">
                    {teacher.avatar ? <img src={teacher.avatar} alt={teacher.name} className="w-full h-full object-cover rounded-lg" /> : teacher.name.charAt(0)}
                  </div>
                )}
                <div className={`max-w-[85%] p-3.5 rounded-2xl text-xs sm:text-sm leading-relaxed ${isUser ? 'bg-indigo-600 text-white rounded-br-none' : 'bg-slate-800 border border-slate-700/80 text-slate-200 rounded-bl-none'}`}>
                  <div className="whitespace-pre-line prose prose-invert prose-xs max-w-none">
                    {msg.role === 'profesor' ? <ReactMarkdown>{msg.texto}</ReactMarkdown> : msg.texto}
                  </div>
                  {msg.timestamp && <span className={`block text-[9px] mt-1 text-right ${isUser ? 'text-indigo-200' : 'text-slate-400'}`}>{msg.timestamp}</span>}
                </div>
              </div>
            );
          })}
          {isLoading && (
            <div className="flex gap-3 items-center text-slate-400 text-xs">
              <Loader2 className="w-4 h-4 animate-spin text-indigo-400" />
              <span>{teacher.name} está formulando una pregunta socrática...</span>
            </div>
          )}
        </div>

        {/* Quick Prompts */}
        <div className="p-2 bg-slate-900 border-t border-slate-800 overflow-x-auto flex items-center gap-1.5">
          <span className="text-[10px] text-slate-400 font-bold uppercase shrink-0 pl-1">Pistas:</span>
          {quickPrompts.map((p, idx) => (
            <button key={idx} onClick={() => handleSendMessage(p)} disabled={isLoading} className="px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-[11px] text-indigo-300 border border-slate-700 whitespace-nowrap">
              {p}
            </button>
          ))}
        </div>

        {/* Input */}
        <form onSubmit={(e) => { e.preventDefault(); handleSendMessage(); }} className="p-3 bg-slate-900 border-t border-slate-800 flex gap-2">
          <input value={input} onChange={(e) => setInput(e.target.value)} disabled={isLoading} placeholder={`Pregunta a ${teacher.name}...`} className="flex-1 bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-xs text-white placeholder-slate-400" />
          <button type="submit" disabled={isLoading || !input.trim()} className="bg-indigo-600 disabled:bg-slate-800 text-white p-2.5 rounded-xl"><Send className="w-4 h-4" /></button>
        </form>
      </div>
    </div>
  );
}
